"""Root fixtures shared by unit and integration tests.

Nothing here touches infrastructure: unit tests must run without PostgreSQL, Redis, etc.
"""

from __future__ import annotations

import json
import time
from collections.abc import Iterator
from pathlib import Path
from typing import Any
from uuid import UUID, uuid4

import pytest

from app.core.config import Settings, get_settings
from app.shared_kernel.domain.tenant import TenantScope

#: Dotenv of the isolated test stack, generated by ``make env-test`` (may be absent).
TEST_ENV_FILE = Path(__file__).resolve().parents[1] / ".env.test"


# --- Requirements report (``--req-report=PATH``) -------------------------------------------
# JUnit cannot carry markers: ``record_property`` is unsupported with the default
# ``junit_family=xunit2`` and xunit1 is legacy. A tiny plugin writes JSON
# ``{nodeid, outcome, duration, reqs}`` instead; ``ops/scripts/test_report.py`` reads it.
# Semantics: one record per test; the first non-passed phase wins (a teardown error after a
# passed call -> "error", counted once, whereas JUnit emits two entries); xfail -> "xfailed",
# xpass -> "xpassed" (unreachable with ``xfail_strict = true`` unless a test opts out).
# Limitations: with pytest-rerunfailures the outcome of the first failed attempt is kept;
# under pytest-xdist the file is written by every process (controller and workers), so
# reports from xdist runs are not supported. Neither plugin is used in this project.


def pytest_addoption(parser: pytest.Parser) -> None:
    parser.addoption(
        "--req-report",
        default=None,
        metavar="PATH",
        help="write JSON with outcome and req(...) codes of every selected test",
    )


def pytest_configure(config: pytest.Config) -> None:
    path = config.getoption("--req-report")
    if path:
        config.pluginmanager.register(_ReqReport(Path(path)), "req-report")


class _ReqReport:
    def __init__(self, path: Path) -> None:
        self.path = path
        self.started = time.monotonic()
        self.tests: dict[str, dict[str, Any]] = {}

    @pytest.hookimpl(trylast=True)  # after -m/-k deselection
    def pytest_collection_modifyitems(self, items: list[pytest.Item]) -> None:
        for item in items:
            reqs = sorted({str(code) for mark in item.iter_markers("req") for code in mark.args})
            self.tests[item.nodeid] = {
                "nodeid": item.nodeid,
                "reqs": reqs,
                "outcome": "not-run",
                "duration": 0.0,
            }

    def pytest_runtest_logreport(self, report: pytest.TestReport) -> None:
        rec = self.tests.get(report.nodeid)
        if rec is None:
            return
        rec["duration"] += report.duration
        if report.when != "call" and report.passed:
            return
        if hasattr(report, "wasxfail"):
            outcome = "xfailed" if report.skipped else "xpassed"
        elif report.failed and report.when != "call":
            outcome = "error"
        else:
            outcome = report.outcome
        if rec["outcome"] in ("not-run", "passed"):
            rec["outcome"] = outcome

    def pytest_sessionfinish(self, exitstatus: int) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = {
            "exitstatus": int(exitstatus),
            "duration": round(time.monotonic() - self.started, 2),
            "tests": list(self.tests.values()),
        }
        self.path.write_text(json.dumps(payload, ensure_ascii=False, indent=1), "utf-8")


@pytest.fixture(scope="session")
def settings() -> Settings:
    """Settings of the test stack: ``.env.test`` when present, otherwise the defaults.

    Real environment variables (``make test-integration`` exports ``POSTGRES_HOST`` /
    ``POSTGRES_PORT`` etc.) take precedence over the dotenv file - the standard
    pydantic-settings source order (init > env > dotenv > defaults).
    """
    if TEST_ENV_FILE.is_file():
        return Settings(_env_file=TEST_ENV_FILE)
    return Settings()


@pytest.fixture(autouse=True)
def _clear_settings_cache() -> Iterator[None]:
    """Keep the ``get_settings()`` ``lru_cache`` from leaking between tests."""
    get_settings.cache_clear()
    yield
    get_settings.cache_clear()


@pytest.fixture(autouse=True)
def _pristine_faststream_logger() -> None:
    """Importing FastStream configures its module-level ``faststream`` logger (own stderr
    handler, ``propagate=False``). Production code never logs through it (the broker gets
    ``logger=`` from ``build_rabbit_broker``), but tests that use the name do - reset it."""
    import logging

    log = logging.getLogger("faststream")
    log.handlers.clear()
    log.propagate = True
    log.setLevel(logging.NOTSET)


